actions.script:
// aggregation metrics are decimals on Postgres and numbers on OpenSearch; the summaries work in numbers
const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())
const addNumbersInMap = (total, line) => {
    for (const [key, value] of Object.entries(line)) if (typeof value === 'number') total[key] = (total[key] || 0) + value
}
const divideNumbersInMap = (map, divisor) => {
    for (const [key, value] of Object.entries(map)) if (typeof value === 'number') map[key] = divisor ? value / divisor : 0
}
const sumOf = (list, field) => list.reduce((total, line) => total + (line[field] || 0), 0)

let maInt = maPeriods || 0
if (maInt < 0) maInt = 0
const displayIntervalCount = interval === 'q' ? (intervalCount * 3) : intervalCount
const searchIntervalCount = displayIntervalCount + maInt

// from the start of the current period back searchIntervalCount days, weeks, months (also for quarters), or years
const perMap = {d:'day', w:'week', M:'month', q:'quarter', y:'year'}
const curPer = ec.user.getPeriodRange(perMap[interval], 0, thruDate)
const thruMillis = Number(curPer[1])
const fromDate = new Date(Number(curPer[0]))
if (interval === 'd') fromDate.setDate(fromDate.getDate() - searchIntervalCount)
else if (interval === 'w') fromDate.setDate(fromDate.getDate() - searchIntervalCount * 7)
else if (interval === 'y') fromDate.setFullYear(fromDate.getFullYear() - searchIntervalCount)
else fromDate.setMonth(fromDate.getMonth() - searchIntervalCount)

// weekly buckets start on Monday unless offset; weeks in getPeriodRange start on Sunday, so match that
if (!offset && interval === 'w') offset = '-1d'

const placedStatuses = ['OrderPlaced', 'OrderProcessing', 'OrderApproved', 'OrderSent', 'OrderCompleted', 'OrderHold']
const filterList = [
        {field: {name: dateField, op: 'range', gte: fromDate.getTime(), lt: thruMillis}},
        {field: {name: 'partStatusId', op: 'in', values: placedStatuses}},
        {field: {name: 'statusId', op: 'in', values: placedStatuses}}
]
if (vendorPartyIds?.length) filterList.push({field: {name: 'vendorPartyId', op: 'in', values: vendorPartyIds}})
if (customerPartyIds?.length) filterList.push({field: {name: 'customerPartyId', op: 'in', values: customerPartyIds}})
if (productStoreIds?.length) filterList.push({field: {name: 'productStoreId', op: 'in', values: productStoreIds}})
if (customerClassificationIds?.length) filterList.push({field: {name: 'customerClassId', op: 'in', values: customerClassificationIds}})
if (productIds?.length) filterList.push({field: {name: 'productId', op: 'in', values: productIds}})

const histoMap = {field:dateField, calendar_interval:('1' + interval), format:dateFormat, order:{_key:'desc'}}
if (offset) histoMap.offset = offset

const discountTypes = ['ItemDiscount', 'ItemPromptDiscount', 'ItemCouponCredit', 'ItemPromoDiscount', 'ItemFreeFills', 'ItemSlottingFees', 'ItemAdjAdvertising', 'ItemAdjJointAdv']
const aggsMap = {DateOuter:{date_histogram:histoMap, aggs:{
    // order count
    orderCount: {cardinality:{field:'orderId'}},
    // total sales (itemSaleTotal, no item type restriction)
    totalSales: {sum:{field:'itemSaleTotal'}},
    // product only sums: sales, shipped (issued), cost, and quantity
    ItemProduct: {filter:{term:{itemTypeEnumId:'ItemProduct'}}, aggs:{
        productSaleTotal: {sum:{field:'itemSaleTotal'}},
        productIssuedTotal: {sum:{field:'issuances.issuedSaleTotal'}},
        productCostTotal: {sum:{field:'issuances.issuedCostTotal'}},
        productQuantityTotal: {sum:{field:'orderQuantity'}}}},
    // total discounts (itemSaleTotal for discount itemTypeEnumId)
    ItemDiscount: {filter:{terms:{itemTypeEnumId:discountTypes}}, aggs:{discountTotal:{sum:{field:'itemSaleTotal'}}}},
    // new customer order count
    NewCustomer: {filter:{term:{isNewCustomer:'Y'}}, aggs:{newCustomerOrderCount:{cardinality:{field:'orderId'}}}}
}}}

if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no sales order summary", "danger"); return }
const aggregationsMap = ec.search.aggregate({documentType:documentType, filter:{bool:{all:filterList}}, aggs:aggsMap})

salesOrderSummaryList = []
ordersTotal = {dateKey:"Prior Total"}
for (const dateBucket of aggregationsMap.DateOuter.buckets) {
    const prodAgg = dateBucket.ItemProduct
    const orderCount = num(dateBucket.orderCount)
    const newCustomerOrderCount = num(dateBucket.NewCustomer.newCustomerOrderCount)
    const productSaleTotal = num(prodAgg.productSaleTotal)
    const productIssuedTotal = num(prodAgg.productIssuedTotal)
    const productCostTotal = num(prodAgg.productCostTotal)
    const discountTotal = num(dateBucket.ItemDiscount.discountTotal)
    const curLine = {dateKey:dateBucket.key_display,
            orderCount:orderCount, newCustomerOrderCount:newCustomerOrderCount,
            newCustomerPercent:(orderCount ? (newCustomerOrderCount/orderCount) : 0.0),
            totalSales:num(dateBucket.totalSales),
            productSaleTotal:productSaleTotal, productIssuedTotal:productIssuedTotal, productCostTotal:productCostTotal,
            productQuantityTotal:num(prodAgg.productQuantityTotal),
            discountTotal:discountTotal, netSales:(productSaleTotal + discountTotal),
            discountPercent:(productSaleTotal ? (-discountTotal/productSaleTotal) : 0.0),
            costPercent:(productIssuedTotal ? (productCostTotal/productIssuedTotal) : 0.0),
            orderCountMa:0.0, newCustomerOrderCountMa:0.0, newCustomerPercentMa:0.0, productQuantityTotalMa:0.0,
            productSaleTotalMa:0.0, discountPercentMa:0.0, netSalesMa:0.0}
    salesOrderSummaryList.push(curLine)
    // don't include the first (most recent) period in the total and average
    if (salesOrderSummaryList.length > 1) addNumbersInMap(ordersTotal, curLine)
}

// get the this, last, prior periods before reversing list
ordersThis = salesOrderSummaryList.length > 0 ? salesOrderSummaryList[0] : null
ordersLast = salesOrderSummaryList.length > 1 ? salesOrderSummaryList[1] : null
ordersPrior = salesOrderSummaryList.length > 2 ? salesOrderSummaryList[2] : null

// reverse the list (buckets come back newest first)
salesOrderSummaryList.reverse()

// calculate moving averages
if (maInt > 0 && salesOrderSummaryList.length > maInt) {
    const originalList = salesOrderSummaryList.slice()
    // trim list for maInt so it has only display periods
    salesOrderSummaryList = originalList.slice(maInt)
    salesOrderSummaryList.forEach((curLine, idx) => {
        const lookbackList = originalList.slice(idx, idx + maInt)
        curLine.orderCountMa = sumOf(lookbackList, 'orderCount') / maInt
        curLine.newCustomerOrderCountMa = sumOf(lookbackList, 'newCustomerOrderCount') / maInt
        curLine.newCustomerPercentMa = sumOf(lookbackList, 'newCustomerPercent') / maInt
        curLine.productQuantityTotalMa = sumOf(lookbackList, 'productQuantityTotal') / maInt
        curLine.productSaleTotalMa = sumOf(lookbackList, 'productSaleTotal') / maInt
        curLine.discountPercentMa = sumOf(lookbackList, 'discountPercent') / maInt
        curLine.netSalesMa = sumOf(lookbackList, 'netSales') / maInt
    })
}

ordersTotal.newCustomerPercent = null
ordersTotal.discountPercent = null
ordersTotal.costPercent = null

ordersAverage = Object.assign({}, ordersTotal)
divideNumbersInMap(ordersAverage, salesOrderSummaryList.length)
ordersAverage.dateKey = "Prior Average"
ordersAverage.newCustomerPercent = (ordersAverage.orderCount ? (ordersAverage.newCustomerOrderCount/ordersAverage.orderCount) : 0.0)
ordersAverage.discountPercent = (ordersAverage.productSaleTotal ? (-ordersAverage.discountTotal/ordersAverage.productSaleTotal) : 0.0)
ordersAverage.costPercent = (ordersAverage.productIssuedTotal ? (ordersAverage.productCostTotal/ordersAverage.productIssuedTotal) : 0.0)

salesOrderSummaryList.push(ordersAverage)
salesOrderSummaryList.push(ordersTotal)

// aggregation metrics are decimals on Postgres and numbers on OpenSearch; the summaries work in numbers
const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())
const addNumbersInMap = (total, line) => {
    for (const [key, value] of Object.entries(line)) if (typeof value === 'number') total[key] = (total[key] || 0) + value
}
const divideNumbersInMap = (map, divisor) => {
    for (const [key, value] of Object.entries(map)) if (typeof value === 'number') map[key] = divisor ? value / divisor : 0
}
const sumOf = (list, field) => list.reduce((total, line) => total + (line[field] || 0), 0)

let maInt = maPeriods || 0
if (maInt < 0) maInt = 0
const displayIntervalCount = interval === 'q' ? (intervalCount * 3) : intervalCount
const searchIntervalCount = displayIntervalCount + maInt

// from the start of the current period back searchIntervalCount days, weeks, months (also for quarters), or years
const perMap = {d:'day', w:'week', M:'month', q:'quarter', y:'year'}
const curPer = ec.user.getPeriodRange(perMap[interval], 0, thruDate)
const thruMillis = Number(curPer[1])
const fromDate = new Date(Number(curPer[0]))
if (interval === 'd') fromDate.setDate(fromDate.getDate() - searchIntervalCount)
else if (interval === 'w') fromDate.setDate(fromDate.getDate() - searchIntervalCount * 7)
else if (interval === 'y') fromDate.setFullYear(fromDate.getFullYear() - searchIntervalCount)
else fromDate.setMonth(fromDate.getMonth() - searchIntervalCount)

// weekly buckets start on Monday unless offset; weeks in getPeriodRange start on Sunday, so match that
if (!offset && interval === 'w') offset = '-1d'

const filterList = [
        {field: {name: dateField, op: 'range', gte: fromDate.getTime(), lt: thruMillis}},
        {field: {name: 'statusId', op: 'in', values: ['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked', 'InvoicePmtRecvd']}}
]
if (fromPartyIds?.length) filterList.push({field: {name: 'fromPartyId', op: 'in', values: fromPartyIds}})
if (toPartyIds?.length) filterList.push({field: {name: 'toPartyId', op: 'in', values: toPartyIds}})
if (productStoreIds?.length) filterList.push({field: {name: 'productStoreId', op: 'in', values: productStoreIds}})
if (customerClassificationIds?.length) filterList.push({field: {name: 'customerClassId', op: 'in', values: customerClassificationIds}})
if (productIds?.length) filterList.push({field: {name: 'productId', op: 'in', values: productIds}})
const filter = {bool:{all:filterList}}

if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no sales invoice summary", "danger"); return }

const invHistoMap = {field:dateField, calendar_interval:('1' + interval), format:dateFormat, order:{_key:'desc'}, min_doc_count:1}
if (offset) invHistoMap.offset = offset
const invAggregationsMap = ec.search.aggregate({documentType:invoiceDocumentType, filter:filter, aggs:{
    DateOuter:{date_histogram:invHistoMap, aggs:{
        invoiceTotal: {sum:{field:'invoiceTotal'}},
        invoicePaymentsApplied: {sum:{field:'appliedPaymentsTotal'}},
        prePaymentsTotal: {sum:{field:'prePaymentsTotal'}}}}}})

const itemHistoMap = {field:dateField, calendar_interval:('1' + interval), format:dateFormat, order:{_key:'desc'}}
if (offset) itemHistoMap.offset = offset
const discountTypes = ['ItemDiscount', 'ItemPromptDiscount', 'ItemCouponCredit', 'ItemPromoDiscount', 'ItemFreeFills', 'ItemSlottingFees', 'ItemAdjAdvertising', 'ItemAdjJointAdv']
const itemAggregationsMap = ec.search.aggregate({documentType:itemDocumentType, filter:filter, aggs:{
    DateOuter:{date_histogram:itemHistoMap, aggs:{
        invoiceIdCount: {cardinality:{field:'invoiceId'}},
        totalSales: {sum:{field:'itemSaleTotal'}},
        ItemProduct: {filter:{term:{itemTypeEnumId:'ItemProduct'}}, aggs:{
            productSaleTotal: {sum:{field:'itemSaleTotal'}},
            productIssuedTotal: {sum:{field:'issuances.issuedSaleTotal'}},
            productCostTotal: {sum:{field:'issuances.issuedCostTotal'}},
            productQuantityTotal: {sum:{field:'quantity'}}}},
        ItemDiscount: {filter:{terms:{itemTypeEnumId:discountTypes}}, aggs:{discountTotal:{sum:{field:'itemSaleTotal'}}}}}}}})

// the two histograms are merged by their formatted date
const invoiceTempMap = {}
for (const dateBucket of invAggregationsMap.DateOuter.buckets) {
    const invoiceTotal = num(dateBucket.invoiceTotal)
    const invoicePaymentsApplied = num(dateBucket.invoicePaymentsApplied)
    const prePaymentsTotal = num(dateBucket.prePaymentsTotal)
    invoiceTempMap[dateBucket.key_display] = {dateKey:dateBucket.key_display, invoiceCount:num(dateBucket.doc_count),
             invoiceTotal:invoiceTotal, invoicePaymentsApplied:invoicePaymentsApplied, prePaymentsTotal:prePaymentsTotal,
             paidPercent:(invoiceTotal ? (invoicePaymentsApplied/invoiceTotal) : 0.0),
             prePaidPercent:(invoiceTotal ? (prePaymentsTotal/invoiceTotal) : 0.0)}
}

salesInvoiceSummaryList = []
invoicesTotal = {dateKey:"Prior Total"}
for (const dateBucket of itemAggregationsMap.DateOuter.buckets) {
    const keyAsString = dateBucket.key_display
    const invoiceTemp = invoiceTempMap[keyAsString]
    delete invoiceTempMap[keyAsString]
    if (!invoiceTemp) ec.logger.warn(`In SalesInvoiceSummary no invoice summary for ${keyAsString}`)
    const prodAgg = dateBucket.ItemProduct
    const invoiceIdCount = num(dateBucket.invoiceIdCount)
    const invoiceCount = (invoiceTemp && invoiceTemp.invoiceCount) || invoiceIdCount
    const productSaleTotal = num(prodAgg.productSaleTotal)
    const productIssuedTotal = num(prodAgg.productIssuedTotal)
    const productCostTotal = num(prodAgg.productCostTotal)
    const discountTotal = num(dateBucket.ItemDiscount.discountTotal)
    const curLine = {invoiceCount:invoiceCount, invoiceIdCount:invoiceIdCount,
            totalSales:num(dateBucket.totalSales),
            productSaleTotal:productSaleTotal, productIssuedTotal:productIssuedTotal, productCostTotal:productCostTotal,
            productQuantityTotal:num(prodAgg.productQuantityTotal),
            discountTotal:discountTotal, netSales:(productSaleTotal + discountTotal),
            discountPercent:(productSaleTotal ? (-discountTotal/productSaleTotal) : 0.0),
            costPercent:(productIssuedTotal ? (productCostTotal/productIssuedTotal) : 0.0),
            invoiceCountMa:0.0, productQuantityTotalMa:0.0, invoiceTotalMa:0.0, paidPercentMa:0.0,
            prePaidPercentMa:0.0, costPercentMa:0.0, discountPercentMa:0.0}
    Object.assign(curLine, invoiceTemp || {dateKey:keyAsString, invoiceTotal:0.0,
            invoicePaymentsApplied:0.0, prePaymentsTotal:0.0, paidPercent:0.0, prePaidPercent:0.0})
    salesInvoiceSummaryList.push(curLine)
    if (salesInvoiceSummaryList.length > 1) addNumbersInMap(invoicesTotal, curLine)
}
if (Object.keys(invoiceTempMap).length) ec.logger.info(`In SalesInvoiceSummary invoiceTempMap remaining: ${JSON.stringify(invoiceTempMap)}`)

invoicesThis = salesInvoiceSummaryList.length > 0 ? salesInvoiceSummaryList[0] : null
invoicesLast = salesInvoiceSummaryList.length > 1 ? salesInvoiceSummaryList[1] : null
invoicesPrior = salesInvoiceSummaryList.length > 2 ? salesInvoiceSummaryList[2] : null

// reverse the list (buckets come back newest first)
salesInvoiceSummaryList.reverse()

// calculate moving averages
if (maInt > 0 && salesInvoiceSummaryList.length > maInt) {
    const originalList = salesInvoiceSummaryList.slice()
    salesInvoiceSummaryList = originalList.slice(maInt)
    salesInvoiceSummaryList.forEach((curLine, idx) => {
        const lookbackList = originalList.slice(idx, idx + maInt)
        curLine.invoiceCountMa = sumOf(lookbackList, 'invoiceCount') / maInt
        curLine.productQuantityTotalMa = sumOf(lookbackList, 'productQuantityTotal') / maInt
        curLine.invoiceTotalMa = sumOf(lookbackList, 'invoiceTotal') / maInt
        curLine.paidPercentMa = sumOf(lookbackList, 'paidPercent') / maInt
        curLine.prePaidPercentMa = sumOf(lookbackList, 'prePaidPercent') / maInt
        curLine.costPercentMa = sumOf(lookbackList, 'costPercent') / maInt
        curLine.discountPercentMa = sumOf(lookbackList, 'discountPercent') / maInt
    })
}

invoicesTotal.paidPercent = null
invoicesTotal.prePaidPercent = null
invoicesTotal.discountPercent = null
invoicesTotal.costPercent = null

invoicesAverage = Object.assign({}, invoicesTotal)
divideNumbersInMap(invoicesAverage, salesInvoiceSummaryList.length)
invoicesAverage.dateKey = "Prior Average"
invoicesAverage.paidPercent = (invoicesAverage.invoiceTotal ? (invoicesAverage.invoicePaymentsApplied/invoicesAverage.invoiceTotal) : 0.0)
invoicesAverage.prePaidPercent = (invoicesAverage.invoiceTotal ? (invoicesAverage.prePaymentsTotal/invoicesAverage.invoiceTotal) : 0.0)
invoicesAverage.discountPercent = (invoicesAverage.productSaleTotal ? (-invoicesAverage.discountTotal/invoicesAverage.productSaleTotal) : 0.0)
invoicesAverage.costPercent = (invoicesAverage.productIssuedTotal ? (invoicesAverage.productCostTotal/invoicesAverage.productIssuedTotal) : 0.0)

salesInvoiceSummaryList.push(invoicesAverage)
salesInvoiceSummaryList.push(invoicesTotal)

const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())

const perMap = {d:'day', w:'week', M:'month', q:'quarter', y:'year'}
const curPer = ec.user.getPeriodRange(perMap[interval], poffset, thruDate)
topProductStart = curPer[0]
topProductEnd = curPer[1]

const placedStatuses = ['OrderPlaced', 'OrderProcessing', 'OrderApproved', 'OrderSent', 'OrderCompleted', 'OrderHold']
const filter = {bool:{all:[
        {field: {name: dateField, op: 'range', gte: Number(topProductStart), lt: Number(topProductEnd)}},
        {field: {name: 'partStatusId', op: 'in', values: placedStatuses}}
]}}

if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no top products", "danger"); return }
const aggregationsMap = ec.search.aggregate({documentType:documentType, filter:filter, aggs:{
    TopTerms:{terms:{field:'productId', size:topLimit, order:{[orderByField]:'desc'}}, aggs:{
        totalQuantity: {sum:{field:'orderQuantity'}},
        totalSales: {sum:{field:'itemSaleTotal'}},
        productIssuedTotal: {sum:{field:'issuances.issuedSaleTotal'}},
        productCostTotal: {sum:{field:'issuances.issuedCostTotal'}}}}}})

topProductList = aggregationsMap.TopTerms.buckets.map((bucket) => {
    const productIssuedTotal = num(bucket.productIssuedTotal)
    const productCostTotal = num(bucket.productCostTotal)
    return {productId:bucket.key, totalQuantity:num(bucket.totalQuantity), totalSales:num(bucket.totalSales),
            productIssuedTotal:productIssuedTotal, productCostTotal:productCostTotal,
            costPercent:(productIssuedTotal ? (productCostTotal/productIssuedTotal) : 0.0)}
})

// aggregation metrics are decimals on Postgres and numbers on OpenSearch; the summaries work in numbers
const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())
const addNumbersInMap = (total, line) => {
    for (const [key, value] of Object.entries(line)) if (typeof value === 'number') total[key] = (total[key] || 0) + value
}
const divideNumbersInMap = (map, divisor) => {
    for (const [key, value] of Object.entries(map)) if (typeof value === 'number') map[key] = divisor ? value / divisor : 0
}
const sumOf = (list, field) => list.reduce((total, line) => total + (line[field] || 0), 0)

const perMap = {d:'day', w:'week', M:'month', q:'quarter', y:'year'}
const curPer = ec.user.getPeriodRange(perMap[interval], poffset, thruDate)
topCustomerClassStart = curPer[0]
topCustomerClassEnd = curPer[1]

const filter = {bool:{all:[
        {field: {name: dateField, op: 'range', gte: Number(topCustomerClassStart), lt: Number(topCustomerClassEnd)}},
        {field: {name: 'statusId', op: 'in', values: ['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked', 'InvoicePmtRecvd']}}
]}}

if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no invoices by customer class", "danger"); return }
const invAggregationsMap = ec.search.aggregate({documentType:invoiceDocumentType, filter:filter, aggs:{
    TopTerms:{terms:{field:'customerClassId', size:topLimit}, aggs:{
        invoiceTotal: {sum:{field:'invoiceTotal'}},
        invoicePaymentsApplied: {sum:{field:'appliedPaymentsTotal'}}}}}})

const discountTypes = ['ItemDiscount', 'ItemPromptDiscount', 'ItemCouponCredit', 'ItemPromoDiscount', 'ItemFreeFills', 'ItemSlottingFees', 'ItemAdjAdvertising', 'ItemAdjJointAdv']
const itemAggregationsMap = ec.search.aggregate({documentType:itemDocumentType, filter:filter, aggs:{
    TopTerms:{terms:{field:'customerClassId', size:topLimit}, aggs:{
        invoiceIdCount: {cardinality:{field:'invoiceId'}},
        totalSales: {sum:{field:'itemSaleTotal'}},
        ItemProduct: {filter:{term:{itemTypeEnumId:'ItemProduct'}}, aggs:{
            productSaleTotal: {sum:{field:'itemSaleTotal'}},
            productIssuedTotal: {sum:{field:'issuances.issuedSaleTotal'}},
            productCostTotal: {sum:{field:'issuances.issuedCostTotal'}},
            productQuantityTotal: {sum:{field:'quantity'}}}},
        ItemDiscount: {filter:{terms:{itemTypeEnumId:discountTypes}}, aggs:{discountTotal:{sum:{field:'itemSaleTotal'}}}}}}}})

const invoiceTempMap = {}
for (const bucket of invAggregationsMap.TopTerms.buckets) {
    const customerClassId = bucket.key
    const invoiceTotal = num(bucket.invoiceTotal)
    const invoicePaymentsApplied = num(bucket.invoicePaymentsApplied)
    invoiceTempMap[customerClassId] = {customerClassId:customerClassId, invoiceCount:num(bucket.doc_count),
            invoiceTotal:invoiceTotal, invoicePaymentsApplied:invoicePaymentsApplied,
            paidPercent:(invoiceTotal ? (invoicePaymentsApplied/invoiceTotal) : 0.0)}
}

invoicesTotal = {classDescription:"Total"}
for (const bucket of itemAggregationsMap.TopTerms.buckets) {
    const customerClassId = bucket.key
    let invoiceTemp = invoiceTempMap[customerClassId]
    if (!invoiceTemp) { invoiceTemp = {customerClassId:customerClassId}; invoiceTempMap[customerClassId] = invoiceTemp }
    const prodAgg = bucket.ItemProduct
    const invoiceIdCount = num(bucket.invoiceIdCount)
    const productSaleTotal = num(prodAgg.productSaleTotal)
    const productIssuedTotal = num(prodAgg.productIssuedTotal)
    const productCostTotal = num(prodAgg.productCostTotal)
    const discountTotal = num(bucket.ItemDiscount.discountTotal)
    Object.assign(invoiceTemp, {invoiceCount:(invoiceTemp.invoiceCount || invoiceIdCount), invoiceIdCount:invoiceIdCount,
            totalSales:num(bucket.totalSales),
            productSaleTotal:productSaleTotal, productIssuedTotal:productIssuedTotal, productCostTotal:productCostTotal,
            productQuantityTotal:num(prodAgg.productQuantityTotal),
            discountTotal:discountTotal, netSales:(productSaleTotal + discountTotal),
            discountPercent:(productSaleTotal ? (-discountTotal/productSaleTotal) : 0.0),
            costPercent:(productIssuedTotal ? (productCostTotal/productIssuedTotal) : 0.0)})
    addNumbersInMap(invoicesTotal, invoiceTemp)
}

topCustomerClassList = Object.values(invoiceTempMap)
orderMapList(topCustomerClassList, [orderByField])
for (const classLine of topCustomerClassList) {
    classLine.classDescription = ec.entity.find("mantle.party.PartyClassification")
            .condition("partyClassificationId", classLine.customerClassId).one()?.description
}

invoicesTotal.paidPercent = null
invoicesTotal.discountPercent = null
invoicesTotal.costPercent = null

topCustomerClassList.push(invoicesTotal)
